class TestOwnershipEnforcement:
    """Validate strict ownership semantics."""

    def test_release_by_non_owner_rejected(self) -> None:
        lock = IdentityLock()
        lock.acquire(timeout=0.0)
        with pytest.raises(LockOwnershipError):
            lock.release(owner_id="intruder")
        lock.release()  # Original owner still holds

    def test_double_release_rejected(self) -> None:
        lock = IdentityLock()
        lock.acquire(timeout=0.0)
        lock.release()
        with pytest.raises(LockOwnershipError):
            lock.release()

    def test_release_without_acquire_rejected(self) -> None:
        lock = IdentityLock()
        with pytest.raises(LockOwnershipError):
            lock.release()

    def test_thread_affinity_enforced(self) -> None:
        lock = IdentityLock(thread_affine=True)
        lock.acquire(timeout=0.0)
        release_error: list[Exception] = []

        def wrong_thread_release() -> None:
            try:
                lock.release()
            except LockOwnershipError as e:
                release_error.append(e)

        t = threading.Thread(target=wrong_thread_release)
        t.start()
        t.join(timeout=1.0)
        assert len(release_error) == 1
        # Original thread can still release
        lock.release()

    def test_owner_id_persistence(self) -> None:
        """Owner ID must be stable across acquire/release cycles."""
        lock = IdentityLock()
        lock.acquire(timeout=0.0)
        owner = lock.owner_id
        assert owner is not None
        lock.release()
        assert lock.owner_id is None

    def test_explicit_owner_id_accepted(self) -> None:
        """Explicit owner ID must be honored."""
        lock = IdentityLock()
        lock.acquire(owner_id="custom-owner", timeout=0.0)
        assert lock.owner_id == "custom-owner"
        lock.release(owner_id="custom-owner")

    def test_wrong_owner_id_release_rejected(self) -> None:
        """Release with wrong explicit owner ID must fail."""
        lock = IdentityLock()
        lock.acquire(owner_id="custom-owner", timeout=0.0)
        with pytest.raises(LockOwnershipError):
            lock.release(owner_id="other-owner")
        lock.release(owner_id="custom-owner")


