class TestReentrancy:
    """Validate reentrant acquisition semantics."""

    def test_reentrant_acquire_same_owner(self) -> None:
        """Same owner can re-acquire without deadlock."""
        lock = IdentityLock()
        lock.acquire(timeout=0.0)
        lock.acquire(timeout=0.0)  # Reentrant
        assert lock.acquire_count == 2
        lock.release()
        lock.release()
        assert lock.acquire_count == 0

    def test_reentrant_release_requires_matching_count(self) -> None:
        """Release must be called as many times as acquire."""
        lock = IdentityLock()
        lock.acquire(timeout=0.0)
        lock.acquire(timeout=0.0)
        lock.release()
        assert lock.acquire_count == 1
        # Lock still held
        with pytest.raises(LockOwnershipError):
            lock.acquire(owner_id="other", timeout=0.0)
        lock.release()

    def test_reentrant_different_owner_rejected(self) -> None:
        """Different owner cannot re-acquire while held."""
        lock = IdentityLock()
        lock.acquire(timeout=0.0)
        with pytest.raises(LockOwnershipError):
            lock.acquire(owner_id="other", timeout=0.0)
        lock.release()

    def test_deep_recursion(self) -> None:
        """Deep reentrancy (100 levels) must work."""
        lock = IdentityLock()
        for _ in range(100):
            lock.acquire(timeout=0.0)
        assert lock.acquire_count == 100
        for _ in range(100):
            lock.release()
        assert lock.acquire_count == 0


