class TestTimeoutSemantics:
    """Validate timeout and non-blocking behavior."""

    def test_acquire_timeout_zero_non_blocking(self) -> None:
        """timeout=0.0 must not block."""
        lock = IdentityLock()
        start = time.monotonic()
        result = lock.acquire(timeout=0.0)
        elapsed = time.monotonic() - start
        assert result is True
        assert elapsed < 0.1  # Should be near-instant

    def test_acquire_timeout_negative_raises(self) -> None:
        """Negative timeout must raise ValueError."""
        lock = IdentityLock()
        with pytest.raises(ValueError):
            lock.acquire(timeout=-1.0)

    def test_acquire_timeout_blocks_until_available(self) -> None:
        """Acquire with timeout must block until lock is released."""
        lock = IdentityLock()
        lock.acquire(timeout=0.0)

        def delayed_release() -> None:
            time.sleep(0.2)
            lock.release()

        t = threading.Thread(target=delayed_release)
        t.start()
        start = time.monotonic()
        result = lock.acquire(timeout=2.0)
        elapsed = time.monotonic() - start
        assert result is True
        assert elapsed >= 0.15  # Must have waited
        t.join()
        lock.release()

    def test_acquire_timeout_expires(self) -> None:
        """Acquire must return False when timeout expires."""
        lock = IdentityLock()
        lock.acquire(timeout=0.0)
        start = time.monotonic()
        result = lock.acquire(timeout=0.1)
        elapsed = time.monotonic() - start
        assert result is False
        assert elapsed >= 0.08  # Must have waited at least ~timeout
        lock.release()

    def test_acquire_timeout_none_blocks_indefinitely(self) -> None:
        """timeout=None must block until available."""
        lock = IdentityLock()
        lock.acquire(timeout=0.0)

        def delayed_release() -> None:
            time.sleep(0.1)
            lock.release()

        t = threading.Thread(target=delayed_release)
        t.start()
        result = lock.acquire(timeout=None)
        assert result is True
        t.join()
        lock.release()


