class TestThreadAffinity:
    """Validate thread-affinity enforcement."""

    def test_non_affine_lock_cross_thread_release(self) -> None:
        """Non-affine lock allows cross-thread release."""
        lock = IdentityLock(thread_affine=False)
        lock.acquire(timeout=0.0)
        results: List[bool] = []

        def cross_release() -> None:
            try:
                lock.release()
                results.append(True)
            except LockOwnershipError:
                results.append(False)

        t = threading.Thread(target=cross_release)
        t.start()
        t.join(timeout=1.0)
        assert results == [True]

    def test_affine_lock_cross_thread_acquire_rejected(self) -> None:
        """Affine lock rejects cross-thread acquire."""
        lock = IdentityLock(thread_affine=True)
        lock.acquire(timeout=0.0)
        results: List[bool] = []

        def cross_acquire() -> None:
            try:
                lock.acquire(timeout=0.1)
                results.append(True)
            except LockOwnershipError:
                results.append(False)

        t = threading.Thread(target=cross_acquire)
        t.start()
        t.join(timeout=1.0)
        assert results == [False]
        lock.release()

    def test_affine_lock_same_thread_reacquire(self) -> None:
        """Affine lock allows same-thread re-acquire."""
        lock = IdentityLock(thread_affine=True)
        lock.acquire(timeout=0.0)
        lock.acquire(timeout=0.0)  # Same thread, should succeed
        assert lock.acquire_count == 2
        lock.release()
        lock.release()

    def test_affine_lock_owner_id_matches_thread(self) -> None:
        """Affine lock owner_id should be thread identifier."""
        lock = IdentityLock(thread_affine=True)
        lock.acquire(timeout=0.0)
        assert lock.owner_id == threading.get_ident()
        lock.release()


