    def test_context_manager_acquires_and_releases(self) -> None:
        """with block must acquire and release properly."""
        lock = IdentityLock()
        with lock:
            assert lock.acquire_count == 1
            assert lock.owner_id is not None
        assert lock.acquire_count == 0
        assert lock.owner_id is None

    def test_context_manager_releases_on_exception(self) -> None:
        """with block must release even on exception."""
        lock = IdentityLock()
        with pytest.raises(RuntimeError):
            with lock:
                raise RuntimeError("boom")
        assert lock.acquire_count == 0
        assert lock.owner_id is None

    def test_context_manager_nested(self) -> None:
        """Nested with blocks must work correctly."""
        lock = IdentityLock()
        with lock:
            with lock:
                assert lock.acquire_count == 2
            assert lock.acquire_count == 1
        assert lock.acquire_count == 0


