# Stress & Chaos Testing
# ---------------------------------------------------------------------------
class TestStress:
    """High-concurrency stress scenarios."""

    def test_concurrent_acquire_release_contention(self) -> None:
        """Multiple threads competing for lock must not corrupt state."""
        lock = IdentityLock(thread_affine=False)
        errors: List[Exception] = []
        success_count = 0
        lock_held = threading.Lock()

        def worker() -> None:
            nonlocal success_count
            for _ in range(100):
                try:
                    if lock.acquire(timeout=1.0):
                        with lock_held:
                            success_count += 1
                        lock.release()
                except Exception as e:  # pragma: no cover - defensive
                    errors.append(e)

        threads = [threading.Thread(target=worker) for _ in range(10)]
        for t in threads:
            t.start()
        for t in threads:
            t.join(timeout=10.0)

        assert not errors
        assert success_count == 1000
        assert lock.acquire_count == 0
        assert lock.owner_id is None

    def test_stress_reentrant_same_thread(self) -> None:
        """Single thread with deep reentrancy under load."""
        lock = IdentityLock()
        for _ in range(1000):
            lock.acquire(timeout=0.0)
        assert lock.acquire_count == 1000
        for _ in range(1000):
            lock.release()
        assert lock.acquire_count == 0

    def test_stress_mixed_operations(self) -> None:
        """Mixed acquire/release/context-manager operations."""
        lock = IdentityLock()
        for i in range(500):
            if i % 2 == 0:
                with lock:
                    assert lock.acquire_count == 1
            else:
                lock.acquire(timeout=0.0)
                lock.release()
        assert lock.acquire_count == 0

    def test_chaos_random_operations(self) -> None:
        """Randomized operations must never corrupt state."""
        import random

        lock = IdentityLock()
        for _ in range(1000):
            op = random.choice(["acquire", "release", "cm"])
            try:
                if op == "acquire":
                    lock.acquire(timeout=0.0)
                elif op == "release":
                    lock.release()
                else:  # cm
                    with lock:
                        pass
            except LockOwnershipError:
                pass  # Expected for invalid sequences
        # Final state must be consistent
        assert lock.acquire_count >= 0
        if lock.acquire_count > 0:
            # Clean up
            for _ in range(lock.acquire_count):
                lock.release()
        assert lock.acquire_count == 0


