class TestPerformance:
    """Performance sanity checks (not strict benchmarks)."""

    @pytest.mark.skipif(
        not __import__("os").environ.get("RUN_PERF_TESTS"),
        reason="Set RUN_PERF_TESTS=1 to enable performance tests",
    )
    def test_acquire_release_latency(self) -> None:
        """Acquire/release must be fast (< 1ms avg)."""
        lock = IdentityLock()
        iterations = 10_000
        start = time.perf_counter()
        for _ in range(iterations):
            lock.acquire(timeout=0.0)
            lock.release()
        elapsed = time.perf_counter() - start
        avg_latency = elapsed / iterations
        assert avg_latency < 0.001, f"Avg latency too high: {avg_latency:.6f}s"

    @pytest.mark.skipif(
        not __import__("os").environ.get("RUN_PERF_TESTS"),
        reason="Set RUN_PERF_TESTS=1 to enable performance tests",
    )
    def test_contention_throughput(self) -> None:
        """Throughput under contention must be reasonable."""
        lock = IdentityLock(thread_affine=False)
        iterations = 1000
        completed = [0]

        def worker() -> None:
            for _ in range(iterations):
                lock.acquire(timeout=1.0)
                lock.release()
                completed[0] += 1

        threads = [threading.Thread(target=worker) for _ in range(4)]
        start = time.perf_counter()
        for t in threads:
            t.start()
        for t in threads:
            t.join(timeout=10.0)
        elapsed = time.perf_counter() - start
        total_ops = completed[0]
        throughput = total_ops / elapsed
        assert throughput > 100, f"Throughput too low: {throughput:.1f} ops/s"


